using System.ComponentModel.DataAnnotations; namespace ApiFromLecture.Validation; public class NotInFutureAttribute:ValidationAttribute{protected override ValidationResult? IsValid(object? value,ValidationContext c){if(value is DateTime dt&&dt>DateTime.UtcNow)return new ValidationResult(ErrorMessage??"Дата не может быть в будущем",new[]{c.MemberName!});return ValidationResult.Success;}}
